# owner: platform
import unittest

from rosterkit.contacts import contact_rows
from rosterkit.models import Student


# ---
def make_student(last, first, section, email):
    return Student(
        f"{last}{first}", last, first, section, email
    )


class ContactRowTests(unittest.TestCase):
    def test_rows_sorted_by_name_and_aligned(self):
        rows = contact_rows([
            make_student("Young", "Zed", "B", "z@x.org"),
            make_student("Adams", "Bea", "A", "b@x.org"),
            make_student("Li", "Cy", "A", "c@x.org")
        ])
        self.assertEqual(rows, [
            "Adams, Bea  A  b@x.org",
            "Li, Cy      A  c@x.org",
            "Young, Zed  B  z@x.org"
        ])

    def test_missing_email_names_student(self):
        students = [
            make_student("Adams", "Bea", "A", "b@x.org"),
            make_student("Li", "Cy", "A", None)
        ]
        with self.assertRaises(ValueError) as caught:
            contact_rows(students)
        self.assertIn("Li, Cy", str(caught.exception))

    def test_blank_email_counts_as_missing(self):
        students = [make_student("Li", "Cy", "A", "  ")]
        with self.assertRaises(ValueError):
            contact_rows(students)

    def test_empty_list_raises(self):
        with self.assertRaises(ValueError):
            contact_rows([])


if __name__ == "__main__":
    unittest.main()
